static long long account = 0;
void deposit(long long);
static void *dep_worker(void *arg) { deposit((long long)(intptr_t)arg); return NULL; }
static long long concurrent_deposits(int nthreads, long long each) {
    pthread_t th[8];
    if (nthreads > 8) nthreads = 8;
    for (int i = 0; i < nthreads; i++) {
        if (pthread_create(&th[i], NULL, dep_worker, (void *)(intptr_t)each) != 0) return -1;
    }
    for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
    return 0;
}

